fn all_characters_same(char_arr: &Vec<char>) -> bool {
    // If the array is empty or has just one element, the condition is vacuously true.
    if char_arr.len() <= 1 {
        return true;
    }

    // Safe to unwrap because len() > 1
    let first = &char_arr[0];
    // Check that every character after the first equals `first`
    char_arr
        .iter()
        .skip(1)
        .all(|c| c == first)
}

